// aim.cpp
// Projects entity head positions to screen space and returns a smoothed
// crosshair delta that is clamped to a 240 px cone around screen centre.
//
// Build (standalone smoke test):
//   cl /std:c++17 /DAIM_SMOKE /W4 /EHsc aim.cpp /Fe:aim_test.exe
//   g++ -std=c++17 -DAIM_SMOKE -O2 -o aim_test aim.cpp

#define WIN32_LEAN_AND_MEAN
#define NOMINMAX
#include <windows.h>
#include <cmath>
#include <cstdint>
#include <cstring>

// ---------------------------------------------------------------------------
// Public interface
// ---------------------------------------------------------------------------

// 3-D world position
struct Vec3 {
    float x, y, z;
};

// 2-D screen position (pixels)
struct Vec2 {
    float x, y;
};

// Camera / view state passed in by the caller
struct ViewState {
    float fovY;            // vertical field-of-view, radians
    float yaw;             // camera yaw,   radians
    float pitch;           // camera pitch, radians
    Vec3  origin;          // camera world position
    int   screenW;         // viewport width  in pixels
    int   screenH;         // viewport height in pixels
};

// Result returned by ComputeAimDelta
struct AimDelta {
    float dx;              // pixel offset from crosshair centre, X axis
    float dy;              // pixel offset from crosshair centre, Y axis
    bool  inCone;          // true when target projects inside the 240 px cone
};

// Persistent smoothing state; zero-initialise before first call.
struct SmoothState {
    float prevDx;
    float prevDy;
};

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

// Forward-vector from yaw/pitch (right-handed, Y-up)
static void CameraAxes(float yaw, float pitch,
                       Vec3& fwd, Vec3& right, Vec3& up)
{
    const float cy = std::cos(yaw),   sy = std::sin(yaw);
    const float cp = std::cos(pitch), sp = std::sin(pitch);

    fwd   = { cy * cp,  sp,  sy * cp };
    right = {     -sy,   0,      cy  };
    up    = { cy * -sp, cp,  sy * -sp };
}

// Project a world-space point to screen pixels.
// Returns false when the point is behind the near plane.
static bool WorldToScreen(const Vec3& world,
                          const ViewState& view,
                          Vec2& screenOut)
{
    // Vector from camera to target
    const Vec3 delta = {
        world.x - view.origin.x,
        world.y - view.origin.y,
        world.z - view.origin.z
    };

    Vec3 fwd, right, up;
    CameraAxes(view.yaw, view.pitch, fwd, right, up);

    // Camera-space coordinates
    const float cx = delta.x * right.x + delta.y * right.y + delta.z * right.z;
    const float cy = delta.x * up.x    + delta.y * up.y    + delta.z * up.z;
    const float cz = delta.x * fwd.x   + delta.y * fwd.y   + delta.z * fwd.z;

    if (cz <= 0.001f) return false;   // behind camera

    // Half-height in world units at depth cz
    const float halfH = std::tan(view.fovY * 0.5f) * cz;
    if (halfH < 1e-6f) return false;

    const float aspect  = static_cast<float>(view.screenW) /
                          static_cast<float>(view.screenH);
    const float halfW   = halfH * aspect;

    screenOut.x = (view.screenW  * 0.5f) + (cx / halfW) * (view.screenW  * 0.5f);
    screenOut.y = (view.screenH  * 0.5f) - (cy / halfH) * (view.screenH  * 0.5f);
    return true;
}

// ---------------------------------------------------------------------------
// Public function
// ---------------------------------------------------------------------------

//  ComputeAimDelta
//
//  Projects `headPos` to screen, computes the delta from the crosshair centre,
//  rejects targets outside a 240 px radius cone, then applies an exponential
//  moving-average smoothing using `smoothFactor` in [0, 1].
//
//  smoothFactor = 0 → no smoothing (raw delta each frame)
//  smoothFactor = 1 → output never changes (fully frozen)
//
//  `state` must persist across frames for the same crosshair / target pair.
AimDelta ComputeAimDelta(const Vec3&       headPos,
                         const ViewState&  view,
                         float             smoothFactor,
                         SmoothState&      state)
{
    // Clamp smoothing factor to a sane range
    if (smoothFactor < 0.0f) smoothFactor = 0.0f;
    if (smoothFactor > 0.99f) smoothFactor = 0.99f;

    constexpr float kConeRadius = 240.0f;  // pixels

    Vec2 screenPos{};
    const bool visible = WorldToScreen(headPos, view, screenPos);

    if (!visible) {
        state.prevDx = 0.0f;
        state.prevDy = 0.0f;
        return { 0.0f, 0.0f, false };
    }

    // Raw delta from screen centre (crosshair)
    const float cx = static_cast<float>(view.screenW) * 0.5f;
    const float cy = static_cast<float>(view.screenH) * 0.5f;

    const float rawDx = screenPos.x - cx;
    const float rawDy = screenPos.y - cy;

    // Cone check
    const float dist2 = rawDx * rawDx + rawDy * rawDy;
    const bool inCone = (dist2 <= kConeRadius * kConeRadius);

    if (!inCone) {
        state.prevDx = 0.0f;
        state.prevDy = 0.0f;
        return { 0.0f, 0.0f, false };
    }

    // Exponential moving average
    const float alpha = 1.0f - smoothFactor;
    const float smDx  = state.prevDx + alpha * (rawDx - state.prevDx);
    const float smDy  = state.prevDy + alpha * (rawDy - state.prevDy);

    state.prevDx = smDx;
    state.prevDy = smDy;

    return { smDx, smDy, true };
}

// ---------------------------------------------------------------------------
// Smoke test (compiled only with -DAIM_SMOKE)
// ---------------------------------------------------------------------------
#ifdef AIM_SMOKE
#include <cstdio>

int main()
{
    ViewState view{};
    view.fovY    = 1.0472f;   // 60 degrees
    view.yaw     = 0.0f;
    view.pitch   = 0.0f;
    view.origin  = { 0.0f, 0.0f, 0.0f };
    view.screenW = 1920;
    view.screenH = 1080;

    // Head 50 units straight ahead, slightly to the right and up
    Vec3 head = { 1.5f, 1.8f, 50.0f };

    SmoothState ss{};
    ss.prevDx = 0.0f;
    ss.prevDy = 0.0f;

    const float smooth = 0.6f;

    printf("Frame  dx        dy        inCone\n");
    printf("-----  --------  --------  ------\n");

    for (int i = 0; i < 8; ++i) {
        AimDelta d = ComputeAimDelta(head, view, smooth, ss);
        printf("  %3d  %8.3f  %8.3f  %s\n",
               i, d.dx, d.dy, d.inCone ? "yes" : "no");
    }

    // Target outside cone
    Vec3 farHead = { 300.0f, 0.0f, 50.0f };
    SmoothState ss2{};
    AimDelta d2 = ComputeAimDelta(farHead, view, smooth, ss2);
    printf("\nOut-of-cone target: dx=%.3f dy=%.3f inCone=%s\n",
           d2.dx, d2.dy, d2.inCone ? "yes" : "no");

    return 0;
}
#endif // AIM_SMOKE
